'use strict';
// Feicoes anuais derivadas dos pixels nativos, preservando mes, classe e georreferencia.
const vectorCache=new Map();let vectorLayer=null,vectorRequest=0;
function vectorDataset(){if(['annual','integration'].includes(state.layer))return `fogo_${state.mapYear}`;if(['recurrence','unique'].includes(state.layer)&&state.month===0&&state.classCode===null&&['2011_2025','2011_2015','2016_2020','2021_2025'].includes(`${state.start}_${state.end}`))return `${state.layer}_${state.start}_${state.end}`;return null;}
async function readVectorDataset(name){if(vectorCache.has(name))return vectorCache.get(name);const r=await fetch(`data/vetores/${name}.geojson.gz`);if(!r.ok)throw Error('Camada vetorial indisponível: '+name);const text=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text();const data=JSON.parse(text);vectorCache.set(name,data);return data;}
function activateMapLayer(value){state.layer=value;stopPlay();syncControls();drawRaster();}
function advancedSync(){const annual=['annual','integration'].includes(state.layer);$('#map-year-wrap').style.display=annual?'flex':'none';$('#play').style.display=annual?'inline-block':'none';$('#map-year-timeline').hidden=!annual;$('#year-slider').min=state.start;$('#year-slider').max=state.end;$('#year-slider').value=state.mapYear;$('#year-value').textContent=state.mapYear;$('#download-vector').style.display=vectorDataset()?'inline-block':'none';$('#download-vector').textContent=annual?'Baixar vetor do ano':'Baixar vetor da camada';$$('[data-map]').forEach(b=>b.classList.toggle('active',b.dataset.map===state.layer));}
async function updateVectorMap(){const request=++vectorRequest;const annual=['annual','integration'].includes(state.layer),dataset=vectorDataset();if(vectorLayer){map.removeLayer(vectorLayer);vectorLayer=null;}rasterLayer.setOpacity(dataset?0:Number($('#opacity').value)/100);if(!dataset){$('#map-info').textContent='Visualização dos pixels nativos de 30 m para os filtros atuais. Clique no território para consultar o histórico. Os mapas anuais e os quatro períodos de referência também têm camadas vetoriais.';return;}
 $('#map-info').textContent=`Carregando as feições vetoriais de ${annual?state.mapYear:state.start+'–'+state.end}…`;
 try{const data=await readVectorDataset(dataset);if(request!==vectorRequest)return;const months=selectedMonths(),filtered={type:'FeatureCollection',features:annual?data.features.filter(f=>months.includes(f.properties.mes)&&(state.classCode===null||f.properties.codigo_original===state.classCode)):data.features};const opacity=Number($('#opacity').value)/100;
 const featureColor=f=>state.layer==='integration'?f.properties.cor:state.layer==='recurrence'?palettes[Math.max(0,Math.min((f.properties.anos_com_queima||1)-1,14))]:'#d95027';
 vectorLayer=L.geoJSON(filtered,{renderer:L.canvas({padding:.2}),bubblingMouseEvents:false,style:f=>({color:featureColor(f),weight:.55,opacity:.95,fillColor:featureColor(f),fillOpacity:opacity}),onEachFeature(f,layer){const p=f.properties;layer.on('mouseover',()=>layer.setStyle({weight:2,color:'#ffffff'}));layer.on('mouseout',()=>vectorLayer?.resetStyle(layer));const title=annual?`Queima mapeada em ${p.ano}`:p.tipo==='recurrence'?`${p.anos_com_queima} anos com queima`:'Área atingida ao menos uma vez';const info=annual?`${MONTHS[p.mes-1]}<br>${esc(p.classe)} · código ${p.codigo_original}`:`Período ${p.inicio}–${p.fim}`;layer.bindPopup(`<h4 class="pixel-head">${title}</h4><p><strong>${info}</strong><br><strong>${fmt(p.area_ha,3)} ha</strong> nesta feição</p><p class="popup-note">${esc(p.id_feicao)}<br>Polígono derivado dos pixels nativos de 30 m.<br>Uma feição não corresponde necessariamente a um incêndio.</p>`);}}).addTo(map);
 if(map.hasLayer(boundary))boundary.bringToFront();$('#map-info').textContent=`${filtered.features.length.toLocaleString('pt-BR')} feições vetoriais de ${annual?state.mapYear:state.start+'–'+state.end}. Clique em um polígono para consultar seus dados. Os indicadores acima mantêm as áreas validadas dos pixels.`;
 if(state.layer==='integration'){const codes=[...new Set(filtered.features.map(f=>f.properties.codigo_original))];$('#map-legend').innerHTML='<div class="class-legend">'+codes.map(c=>{const l=tables.legend.find(x=>x.codigo_original===c);return `<span><i style="background:${l.cor}"></i> ${esc(l.classe)}</span>`;}).join('')+'</div>';}
 }catch(e){if(request===vectorRequest){$('#map-info').textContent=e.message;rasterLayer.setOpacity(Number($('#opacity').value)/100);console.error(e);}}
}
async function setupVectorMaps(){const originalSync=syncControls,originalDraw=drawRaster,originalDesc=mapDescription;syncControls=function(){originalSync();advancedSync();};mapDescription=function(){return state.layer==='integration'?`Queima e cobertura do mesmo ano · ${state.mapYear} · ${monthLabel()}`:originalDesc();};drawRaster=function(){originalDraw();advancedSync();void updateVectorMap();};
 $$('[data-map]').forEach(b=>b.onclick=()=>activateMapLayer(b.dataset.map));$('#map-layer').onchange=e=>activateMapLayer(e.target.value);$('#year-slider').oninput=e=>{state.mapYear=Number(e.target.value);$('#map-year').value=state.mapYear;$('#year-value').textContent=state.mapYear;drawRaster();};$('#opacity').oninput=e=>{const v=Number(e.target.value)/100;$('#opacity-value').value=Math.round(v*100)+'%';if(vectorLayer)vectorLayer.setStyle({fillOpacity:v});else rasterLayer.setOpacity(v);};$('#boundary-toggle').onchange=e=>e.target.checked?boundary.addTo(map):map.removeLayer(boundary);
 $('#expand-map').onclick=()=>{const open=$('#main').classList.toggle('map-expanded');$('#expand-map').textContent=open?'Recolher mapa':'Ampliar mapa';$('#expand-map').setAttribute('aria-pressed',String(open));requestAnimationFrame(()=>{map.invalidateSize();map.fitBounds(boundary.getBounds(),{padding:[20,20]});});};$('#download-boundary').onclick=()=>{const a=document.createElement('a');a.href='data/limite.geojson';a.download='Limite_Lavras_EPSG4326.geojson';a.click();};$('#download-vector').onclick=()=>{const name=vectorDataset();if(!name)return;const a=document.createElement('a');a.href=`data/vetores/${name}.geojson`;a.download=`Lavras_${name}_EPSG4326.geojson`;a.click();};
 $('#focus-feature').onclick=()=>{if(!vectorLayer)return;const layers=vectorLayer.getLayers();if(!layers.length)return;const largest=layers.reduce((a,b)=>a.feature.properties.area_ha>b.feature.properties.area_ha?a:b);map.fitBounds(largest.getBounds(),{padding:[55,55],maxZoom:15});largest.openPopup();};
 // Dados anuais continuam acessiveis mesmo quando o mapa foi ampliado.
 advancedSync();void updateVectorMap();
}
const waitForStudy=setInterval(()=>{if(initialized&&map){clearInterval(waitForStudy);setupVectorMaps();}},100);
